def min_distance_to_zero(n, arr):
    left_dist = [float('inf')] * n
    right_dist = [float('inf')] * n

    # Calculate minimum distance from left
    last_zero = -1
    for i in range(n):
        if arr[i] == 0:
            last_zero = i
        else:
            if last_zero != -1:
                left_dist[i] = i - last_zero

    # Calculate minimum distance from right
    last_zero = -1
    for i in range(n-1, -1, -1):
        if arr[i] == 0:
            last_zero = i
        else:
            if last_zero != -1:
                right_dist[i] = last_zero - i

    # Combine left and right distances
    for i in range(n):
        if left_dist[i] < float('inf') and right_dist[i] < float('inf'):
            arr[i] = min(left_dist[i], right_dist[i])
        elif left_dist[i] < float('inf'):
            arr[i] = left_dist[i]
        else:
            arr[i] = right_dist[i]

    return arr

