def min_distance_to_zero(n, arr):
    left_dist = [float('inf')] * n
    right_dist = [float('inf')] * n

    last_zero = -1
    for i in range(n):
        if arr[i] == 0:
            last_zero = i
        elif last_zero != -1:
            left_dist[i] = i - last_zero

    last_zero = -1
    for i in range(n-1, -1, -1):
        if arr[i] == 0:
            last_zero = i
        elif last_zero != -1:
            right_dist[i] = last_zero - i

    for i in range(n):
        left_dist[i] = min(left_dist[i], right_dist[i])

    return ' '.join(map(str, left_dist))

